let activeGroup='',activeTeam='',scannerStream=null,scannerLoopTimer=null,isScanning=false,deferredInstallPrompt=null;
const state=JSON.parse(localStorage.getItem('albumCopa2026StatusV3')||'{}');
if(localStorage.getItem('albumTheme')==='dark')document.body.classList.add('dark');
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const stickers=STICKER_BASE;
const VALID_CODES=Array.from(new Set(stickers.map(x=>x.teamCode)));
function save(){localStorage.setItem('albumCopa2026StatusV3',JSON.stringify(state));renderAll()}
function getStatus(id){return state[id]||'none'}
function setStatus(id,status){if(status==='none')delete state[id];else state[id]=status;save()}
function cycleStatus(id){const a=['none','have','missing','repeat'];setStatus(id,a[(a.indexOf(getStatus(id))+1)%a.length])}
function statusLabel(s){return{have:'Tenho',missing:'Falta',repeat:'Repetida',none:'Não marcada'}[s]}
function statusEmoji(s){return{have:'✅',missing:'❌',repeat:'🔁',none:'⭕'}[s]}
function counts(list=stickers){return{have:list.filter(x=>getStatus(x.id)==='have').length,repeat:list.filter(x=>getStatus(x.id)==='repeat').length,missing:list.filter(x=>getStatus(x.id)==='missing').length,none:list.filter(x=>getStatus(x.id)==='none').length,total:list.length}}
function pct(h,t){return t?Math.round(h/t*100):0}
function cleanSigla(s){
  s=String(s||'').toUpperCase().replace(/[^A-Z0-9]/g,'');

  // Correções somente quando são muito seguras.
  const safe={
    'C4N':'CAN','CAH':'CAN',
    '8RA':'BRA','BR4':'BRA',
    'AR6':'ARG','4RG':'ARG',
    'P0R':'POR',
    'US4':'USA','U5A':'USA',
    'K5A':'KSA','KSA':'KSA',
    '5UI':'SUI','SU1':'SUI',
    'C0D':'COD',
    'K0R':'KOR'
  };
  if(safe[s]) return safe[s];

  // Não força uma sigla para outra se não tiver certeza.
  s=s.replace(/4/g,'A').replace(/8/g,'B').replace(/5/g,'S').replace(/0/g,'O');
  return VALID_CODES.includes(s)?s:'';
}

function parseCode(q){
  const raw=String(q||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  const m=raw.match(/^([A-Z0-9]{3})([0-9OIL]{1,2})$/);
  if(!m)return null;

  const sig=cleanSigla(m[1]);
  const num=parseInt(String(m[2]).replace(/O/g,'0').replace(/[IL]/g,'1'),10);

  if(!sig || !Number.isFinite(num))return null;

  // Busca real: sigla + número. Não usa id com zero à esquerda.
  return stickers.find(x=>x.teamCode===sig && Number(x.number)===num) || null;
}

function findSticker(q){return parseCode(q)||stickers.find(x=>norm(x.name).includes(norm(q))||norm(x.team).includes(norm(q))||norm(x.group).includes(norm(q)))||null}
function matchesText(x,q){q=String(q||'').trim();if(!q)return true;return !!parseCode(q)&&parseCode(q).id===x.id||norm(x.name).includes(norm(q))||norm(x.team).includes(norm(q))||norm(x.teamCode).includes(norm(q))||norm(x.group).includes(norm(q))}
function normalizeOcrText(t){return String(t||'').toUpperCase().replace(/[|!]/g,'I').replace(/[€¢]/g,'C').replace(/[^A-Z0-9\-\s]/g,' ').replace(/\s+/g,' ').trim()}
function extractFromText(t){const up=normalizeOcrText(t);const variants=[up,up.replace(/\s+/g,''),up.replace(/O(?=\d)/g,'0').replace(/[IL](?=\d)/g,'1'),up.replace(/\s+/g,'').replace(/O(?=\d)/g,'0').replace(/[IL](?=\d)/g,'1')];for(const v of variants){const re=/([A-Z0-9]{3})\s*[-]?\s*([0-9OIL]{1,2})/g;let m;while((m=re.exec(v))){const item=parseCode(m[1]+m[2]);if(item)return item}}return null}
function makeCrop(src, r, scale=8, mode='contrast'){
  const out=document.createElement('canvas');
  const sx=Math.max(0,Math.floor(src.width*r.x));
  const sy=Math.max(0,Math.floor(src.height*r.y));
  const sw=Math.min(src.width-sx,Math.floor(src.width*r.w));
  const sh=Math.min(src.height-sy,Math.floor(src.height*r.h));

  // Super ampliação para letras pequenas da sigla.
  out.width=Math.max(1,sw*scale);
  out.height=Math.max(1,sh*scale);

  const o=out.getContext('2d');
  o.imageSmoothingEnabled=false;
  o.drawImage(src,sx,sy,sw,sh,0,0,out.width,out.height);

  const img=o.getImageData(0,0,out.width,out.height),d=img.data;

  // Contraste seguro + tons de cinza, sem estourar para branco
  for(let i=0;i<d.length;i+=4){
    let g=d[i]*.299+d[i+1]*.587+d[i+2]*.114;
    if(mode==='binary'){
      g = g < 145 ? 0 : 255;
    }else{
      g=Math.max(20,Math.min(235,(g-100)*1.85+135));
    }
    d[i]=d[i+1]=d[i+2]=g;
  }
  o.putImageData(img,0,0);

  // Nitidez leve usando filtro nativo: ajuda letras pequenas
  const sharp=document.createElement('canvas');
  sharp.width=out.width;
  sharp.height=out.height;
  const s=sharp.getContext('2d');
  s.filter='contrast(1.25) brightness(1.06)';
  s.drawImage(out,0,0);
  s.filter='none';

  return sharp;
}

// Para câmera: lê só o quadro central.
// Para foto enviada: procura a etiqueta no topo direito da figurinha.
function buildCodeCrops(src, mode='camera'){
  const cameraRegions=[
    {x:.18,y:.34,w:.64,h:.28}, // quadro central
    {x:.12,y:.30,w:.76,h:.36}  // margem caso zoom varie
  ];

  // Foto enviada: rápido, só topo direito + fallback superior.
  const photoRegions=[
    {x:.48,y:.00,w:.50,h:.22}, // topo direito aberto
    {x:.54,y:.02,w:.42,h:.18}, // etiqueta padrão
    {x:.00,y:.00,w:1.00,h:.28} // fallback faixa superior
  ];

  const regions = mode==='photo' ? photoRegions : cameraRegions;
  const crops=[];
  regions.forEach(r=>{
    crops.push(makeCrop(src,r,8,'contrast'));
    crops.push(makeCrop(src,r,10,'contrast'));
  });
  return crops;
}

async function ocr(canvas){
  if(!window.Tesseract)throw new Error('OCR não carregou');

  const config={
    tessedit_char_whitelist:'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 ',
    tessedit_pageseg_mode:'7',
    preserve_interword_spaces:'1'
  };

  const r=await Tesseract.recognize(canvas,'eng',config);
  return r?.data?.text||'';
}

async function analyzeCanvas(canvas, mode='camera'){
  const crops=buildCodeCrops(canvas, mode);
  let allText='';

  for(const c of crops){
    const text=await ocr(c);
    allText+=' '+text;
    const item=extractFromText(allText);

    // Só aceita se achou na base por SIGLA + NÚMERO.
    if(item) return item;
  }

  return null;
}


function showPhotoPreview(canvas){
  const p=document.getElementById('enhancedPreview');
  if(!p)return;
  p.className='enhanced-preview';
  p.width=canvas.width;
  p.height=canvas.height;
  p.getContext('2d').drawImage(canvas,0,0);
}

function imageFileToCanvas(file){return new Promise((res,rej)=>{const img=new Image();img.onload=()=>{const c=document.createElement('canvas');const max=1000,ratio=Math.min(1,max/Math.max(img.width,img.height));c.width=Math.round(img.width*ratio);c.height=Math.round(img.height*ratio);c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(img.src);res(c)};img.onerror=rej;img.src=URL.createObjectURL(file)})}
function showFound(item){$('#quickCode').value=`${item.teamCode} ${item.number}`;renderQuick(item);$('#scannerStatus').textContent=`Encontrado: ${item.teamCode} ${item.number} • ${item.name}`;scrollTo({top:$('#quickResult').offsetTop-20,behavior:'smooth'})}

async function applyBestCameraZoom(){
  if(!scannerStream) return false;
  const track=scannerStream.getVideoTracks()[0];
  if(!track || !track.getCapabilities || !track.applyConstraints) return false;

  const caps=track.getCapabilities();
  if(!caps.zoom) return false;

  // Usa zoom alto, mas não máximo absoluto para evitar tremedeira/foco ruim.
  const min=caps.zoom.min || 1;
  const max=caps.zoom.max || min;
  const target=Math.min(max, Math.max(min, max >= 3 ? 2.4 : max));

  try{
    await track.applyConstraints({advanced:[{zoom:target}]});
    $('#scannerStatus').innerHTML=`Zoom da câmera aplicado: <strong>${target.toFixed(1)}x</strong>. Mire a etiqueta.`;
    return true;
  }catch(e){
    return false;
  }
}

async function cycleCameraZoom(){
  if(!scannerStream){
    $('#scannerStatus').textContent='Abra o leitor primeiro.';
    return;
  }
  const track=scannerStream.getVideoTracks()[0];
  if(!track || !track.getCapabilities || !track.applyConstraints){
    $('#scannerStatus').textContent='Este navegador não permite controlar zoom.';
    return;
  }
  const caps=track.getCapabilities();
  if(!caps.zoom){
    $('#scannerStatus').textContent='Este aparelho/navegador não liberou zoom da câmera.';
    return;
  }
  const current=(track.getSettings && track.getSettings().zoom) || caps.zoom.min || 1;
  const max=caps.zoom.max || current;
  const min=caps.zoom.min || 1;
  let next=current + 0.7;
  if(next > max) next=min;
  try{
    await track.applyConstraints({advanced:[{zoom:next}]});
    $('#scannerStatus').innerHTML=`Zoom ajustado: <strong>${next.toFixed(1)}x</strong>.`;
  }catch(e){
    $('#scannerStatus').textContent='Não consegui ajustar o zoom.';
  }
}

async function startScanner(){try{scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});$('#scannerVideo').srcObject=scannerStream;await $('#scannerVideo').play();await applyBestCameraZoom();$('#scannerStatus').textContent='Leitor ligado. Mire a etiqueta; usando zoom quando disponível.';scannerLoopTimer=setInterval(scanFrame,900)}catch(e){$('#scannerStatus').textContent='Não consegui abrir a câmera.'}}
function stopScanner(){if(scannerLoopTimer)clearInterval(scannerLoopTimer);scannerLoopTimer=null;if(scannerStream)scannerStream.getTracks().forEach(t=>t.stop());scannerStream=null;$('#scannerVideo').srcObject=null;$('#scannerStatus').textContent='Leitor fechado.'}
async function scanFrame(){if(isScanning||!scannerStream)return;isScanning=true;const v=$('#scannerVideo'),c=$('#scannerCanvas');c.width=v.videoWidth||1280;c.height=v.videoHeight||720;c.getContext('2d').drawImage(v,0,0,c.width,c.height);try{const item=await analyzeCanvas(c,'camera');if(item){stopScanner();showFound(item)}else{$('#scannerStatus').innerHTML='Lendo... aproxime a <strong>etiqueta</strong> para melhorar a sigla.'}}catch(e){}isScanning=false}
async function handlePhotoUpload(e){const file=e.target.files&&e.target.files[0];if(!file)return;$('#scannerStatus').textContent='Lendo foto rapidamente na área da etiqueta...';try{const c=await imageFileToCanvas(file);showPhotoPreview(c);const item=await analyzeCanvas(c,'photo');if(item)showFound(item);else $('#scannerStatus').textContent='Não consegui ler. Tire a foto mais perto da etiqueta, deixando a sigla bem visível.'}catch(err){$('#scannerStatus').textContent='Erro ao ler foto.'}finally{e.target.value=''}}
function renderDashboard(){const c=counts(),p=pct(c.have,c.total);$('#haveCount').textContent=c.have;$('#repeatCount').textContent=c.repeat;$('#missingCount').textContent=c.missing;$('#totalCount').textContent=c.total;$('#homeRepeatCount').textContent=c.repeat;$('#homeMissingCount').textContent=c.missing;$('#percent').textContent=p+'%';$('#barFill').style.width=p+'%';$('#progressText').textContent=`${c.have} de ${c.total} figurinhas marcadas como tenho`}
function openView(n){$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===n));$$('.view').forEach(v=>v.classList.remove('active'));$('#'+n).classList.add('active');if(n==='album')renderCards();if(n==='trades')renderTrades();scrollTo({top:0,behavior:'smooth'})}
function selectGroup(g){activeGroup=g;activeTeam='';$('#search').value='';renderGroupSelector();renderTeamSelector();openView('home')}
function selectTeam(t){const f=stickers.find(x=>x.team===t);activeTeam=t;activeGroup=f?f.group:activeGroup;$('#search').value='';$('#statusFilter').value='all';renderGroupSelector();renderTeamSelector();openView('album')}
function clearSelection(){activeGroup='';activeTeam='';$('#search').value='';$('#statusFilter').value='all';renderGroupSelector();renderTeamSelector();renderCards()}
function applyFilters(x){const q=$('#search')?.value||'',st=$('#statusFilter')?.value||'all';return(!activeGroup||x.group===activeGroup)&&(!activeTeam||x.team===activeTeam)&&(st==='all'||getStatus(x.id)===st)&&matchesText(x,q)}
function renderGroupSelector(){$('#groupSelector').innerHTML=GROUPS.map(g=>{const items=stickers.filter(x=>x.group===g.name),c=counts(items),p=pct(c.have,c.total);return`<button class="group-btn ${activeGroup===g.name?'active':''}" onclick="selectGroup('${g.name}')"><b>${g.name}</b><br><small>✅ ${c.have}/${c.total} · ${p}%</small></button>`}).join('')}
function renderTeamSelector(){const gs=activeGroup?GROUPS.filter(g=>g.name===activeGroup):GROUPS;$('#teamSelector').innerHTML=gs.flatMap(g=>g.teams).map(t=>{const items=stickers.filter(x=>x.team===t.team),c=counts(items),p=pct(c.have,c.total);return`<button class="team-card" onclick="selectTeam('${t.team}')"><header><b>${t.team}</b><span>${t.code}</span></header><div class="smallbar"><i style="width:${p}%"></i></div><div class="mini-counts">✅ ${c.have} · ❌ ${c.missing} · 🔁 ${c.repeat} · ⭕ ${c.none}</div></button>`}).join('')}
function renderTeamProgress(){$('#teamProgress').innerHTML=GROUPS.flatMap(g=>g.teams.map(t=>({...t,group:g.name}))).map(t=>{const items=stickers.filter(x=>x.team===t.team),c=counts(items),p=pct(c.have,c.total);return`<div class="team-row" onclick="selectTeam('${t.team}')"><header><span>${t.team} <small class="muted">${t.code}</small></span><span>${p}%</span></header><div class="smallbar"><i style="width:${p}%"></i></div><small class="muted">${t.group} · ✅ ${c.have} · ❌ ${c.missing} · 🔁 ${c.repeat}</small></div>`}).join('')}
function renderActiveFilters(){const chips=[];if(activeGroup)chips.push(`📌 ${activeGroup}`);if(activeTeam)chips.push(`⚽ ${activeTeam}`);const st=$('#statusFilter')?.value;if(st&&st!=='all')chips.push(`${statusEmoji(st)} ${statusLabel(st)}`);const q=$('#search')?.value;if(q)chips.push(`🔎 ${q}`);$('#activeFilters').innerHTML=chips.map(x=>`<span class="chip">${x}</span>`).join('')}
function renderCards(){const filtered=stickers.filter(applyFilters),c=counts(filtered);$('#albumTitle').textContent=activeTeam||activeGroup||'Figurinhas';$('#albumSubtitle').textContent=`${filtered.length} figurinhas · ✅ ${c.have} · ❌ ${c.missing} · 🔁 ${c.repeat}`;renderActiveFilters();$('#cards').innerHTML=filtered.slice(0,260).map(cardHTML).join('')||'<div class="notice">Nenhuma figurinha encontrada.</div>'}
function cardHTML(x){const st=getStatus(x.id);return`<article class="card"><div class="code" onclick="cycleStatus('${x.id}')">${x.teamCode} ${x.number}</div><div class="team-name">${x.team}</div><div class="player-name">${x.name}</div><small>${x.group}</small><span class="tag ${st}">${statusEmoji(st)} ${statusLabel(st)}</span><div class="status-actions"><button class="${st==='have'?'active':''}" onclick="setStatus('${x.id}','have')">✅ Tenho</button><button class="${st==='missing'?'active':''}" onclick="setStatus('${x.id}','missing')">❌ Falta</button><button class="${st==='repeat'?'active':''}" onclick="setStatus('${x.id}','repeat')">🔁 Repetida</button><button onclick="setStatus('${x.id}','none')">Limpar</button></div></article>`}
function renderQuick(x){if(!x){$('#quickResult').innerHTML='<div class="notice">Não encontrado. Use exemplo: CRO 1, CAN 15.</div>';return}$('#quickResult').innerHTML=cardHTML(x)}
function listByStatus(st){return stickers.filter(x=>getStatus(x.id)===st).map(x=>`${x.teamCode} ${x.number} - ${x.name} (${x.team})`).join('\n')}
function renderTrades(){$('#repeatList').value=listByStatus('repeat')||'Nenhuma repetida marcada ainda.';$('#missingList').value=listByStatus('missing')||'Nenhuma faltante marcada ainda.'}
function tradeMessage(){return`🏆 Álbum Copa 2026\n\n🔁 Tenho repetidas:\n${$('#repeatList').value}\n\n❌ Preciso:\n${$('#missingList').value}`}
function shareTrades(){open('https://wa.me/?text='+encodeURIComponent(tradeMessage()),'_blank')}
async function copyTrades(){try{await navigator.clipboard.writeText(tradeMessage());alert('Lista copiada!')}catch(e){alert('Não consegui copiar.')}}
function setupInstall(){const btn=$('#installBtn');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e});btn.addEventListener('click',async()=>{if(deferredInstallPrompt){deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null}else alert('No Android: Chrome → 3 pontinhos → Instalar aplicativo.')})}
function renderAll(){renderDashboard();renderGroupSelector();renderTeamSelector();renderTeamProgress();renderCards();renderTrades()}
$$('.bottom-nav button').forEach(b=>b.addEventListener('click',()=>openView(b.dataset.view)));$$('[data-open-view]').forEach(b=>b.addEventListener('click',()=>openView(b.dataset.openView)));$('#findBtn').addEventListener('click',()=>renderQuick(findSticker($('#quickCode').value)));$('#quickCode').addEventListener('input',e=>{if(e.target.value.trim().length>=2)renderQuick(findSticker(e.target.value))});$('#search').addEventListener('input',renderCards);$('#statusFilter').addEventListener('change',renderCards);$('#clearSelectionBtn').addEventListener('click',clearSelection);$('#themeBtn').addEventListener('click',()=>{document.body.classList.toggle('dark');localStorage.setItem('albumTheme',document.body.classList.contains('dark')?'dark':'light');$('#themeBtn').textContent=document.body.classList.contains('dark')?'☀️':'🌙'});$('#themeBtn').textContent=document.body.classList.contains('dark')?'☀️':'🌙';$('#shareBtn').addEventListener('click',shareTrades);$('#copyBtn').addEventListener('click',copyTrades);$('#startScannerBtn').addEventListener('click',startScanner);$('#zoomBtn').addEventListener('click',cycleCameraZoom);$('#stopScannerBtn').addEventListener('click',stopScanner);$('#photoInput').addEventListener('change',handlePhotoUpload);setupInstall();if('serviceWorker'in navigator)navigator.serviceWorker.register('service-worker.js').catch(()=>{});renderAll();
